package kr.workbench;
import javax.swing.*;import java.awt.*;import java.awt.image.*;import java.util.*;import javax.imageio.ImageIO;
public class EnvironmentPreview {
 static void layout(Component c){if(c instanceof Container x){if(x instanceof JScrollPane sp&&sp.getViewport().getView() instanceof JTable t)sp.setColumnHeaderView(t.getTableHeader());x.doLayout();for(Component child:x.getComponents())layout(child);}}
 public static void main(String[] args)throws Exception{SwingUtilities.invokeAndWait(()->{try{Font f=Font.createFonts(new java.io.File("/workspace/scratch/NanumGothic-Regular.ttf"))[0].deriveFont(13f);GraphicsEnvironment.getLocalGraphicsEnvironment().registerFont(f);for(Object key:new ArrayList<>(UIManager.getDefaults().keySet()))if(UIManager.get(key) instanceof Font)UIManager.put(key,f);
 EnvironmentPanel p=new EnvironmentPanel(null);var site=p.catalog.observe("http://127.0.0.1:8088/","Server: nginx\nContent-Type: application/vnd.spring-boot.actuator.v3+json","<script src='/swagger-ui/swagger-ui.js'></script>");p.origins.addItem(site.origin);for(int i=0;i<p.tech.getRowCount();i++)if(p.tech.getValueAt(i,0).equals("프레임워크")){p.technologies.setRowSelectionInterval(i,i);break;}String u=p.candidates.get(0).url();p.packets.put(u,new EnvironmentPanel.Packet(u,"GET "+java.net.URI.create(u).getPath()+" HTTP/1.1\r\nHost: 127.0.0.1:8088\r\n\r\n","HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n{\"status\":\"UP\",\"components\":{\"database\":{\"status\":\"UP\",\"details\":{\"database\":\"PostgreSQL\",\"valid\":true}}},\"checks\":[\"readiness\",\"liveness\"]}","HTTP 200"));p.refresh();p.pathTable.setRowSelectionInterval(0,0);p.addNotify();p.setSize(1600,980);for(int i=0;i<3;i++)layout(p);((JSplitPane)UiLayoutTest.named(p,"wb.environment.lists")).setDividerLocation(.30);((JSplitPane)UiLayoutTest.named(p,"wb.environment.workspace")).setDividerLocation(.45);((JSplitPane)UiLayoutTest.named(p,"wb.environment.messages")).setDividerLocation(.5);for(int i=0;i<3;i++)layout(p);BufferedImage image=new BufferedImage(1600,980,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();p.printAll(g);g.dispose();ImageIO.write(image,"png",new java.io.File(args[0]));p.close();}catch(Exception e){throw new RuntimeException(e);}});}
}
